def apply_history_read_source(body, key):
    recipe = RECIPES[key]
    digest = lambda text: hashlib.sha256(text.encode('utf-8')).hexdigest()
    if digest(body) != recipe['originalSha256LF']:
        raise ValueError('History read source original pin mismatch: ' + key)
    original = body
    for edit in recipe['edits']:
        at = edit['index']; before = edit['before']
        if body.count(before) != 1 or body[at:at+len(before)] != before:
            raise ValueError('History read source exact span mismatch: ' + edit['label'])
        body = body[:at] + edit['after'] + body[at+len(before):]
    if digest(body) != recipe['afterSha256LF']:
        raise ValueError('History read source final pin mismatch: ' + key)
    inverse = body
    for edit in reversed(recipe['edits']):
        at = edit['index']; after = edit['after']
        if inverse[at:at+len(after)] != after:
            raise ValueError('History read source inverse span mismatch: ' + edit['label'])
        inverse = inverse[:at] + edit['before'] + inverse[at+len(after):]
    if inverse != original:
        raise ValueError('History read source full inverse mismatch: ' + key)
    return body, dict(originalSha256LF=recipe['originalSha256LF'],
        afterSha256LF=recipe['afterSha256LF'], edits=recipe['edits'],
        fullOriginalInverseExact=True, scope='Actual History list/search read provenance only; no navigation, logout or write replay')
